    'UI_STRATEGY_FULL_TOOLTIPS' => "Úplné zálohovanie vedie k výkonu zálohovania pre všetky zdrojové údaje zálohy. Po dokončení zálohovania sa údaje zo zálohy stanú úplným časom zálohovania, ktorý obsahuje všetky údaje. ",
    'UI_STRATEGY_INCR_TOOLTIPS' => " Prírastková záloha je bežný typ zálohy, ktorý zálohuje iba údaje, ktoré boli vytvorené alebo upravené od poslednej zálohy. Spolieha sa na predchádzajúci ľubovoľný bod zálohy, zálohuje iba zmenené údaje z poslednej zálohy na aktuálny čas. ",
    'UI_STRATEGY_DIFF_TOOLTIPS' => " Rozdielová záloha je typ zálohy údajov, ktorá uchováva údaje a ukladá iba rozdiel v údajoch od poslednej úplnej zálohy. Spolieha sa na posledný úplný bod zálohy, zálohuje iba zmenené údaje z poslednej úplnej zálohy do aktuálneho času. ",
    'UI_STRATEGY_PINCR_TOOLTIPS' => "永久增量为，在做备份任务时，只需做一次完全备份，以后只做增量备份。永久增量只做一次完全备份，减少完全备份次数，节省备份存储空间及带宽资源",
    'UI_STRATEGY_THREE_TOOLTIPS' => "Vo všeobecnosti vám odporúčame vykonať úplnú zálohu týždenne / mesačne a denne vykonať prírastkovú zálohu. Prírastkové zálohovanie a rozdielové zálohovanie nie je možné zvoliť súčasne. Ak vyberiete iba prírastkové zálohovanie alebo rozdielové zálohovanie, prvá aktivovaná úloha zálohovania sa zníži na úplnú zálohu. ",
    'UI_STRATEGY_LOG_TOOLTIPS_MYSQL' => "日志备份是在上一次日志备份或完全备份的基础上,对比变化的日志数据",
    'UI_STRATEGY_LOG_TOOLTIPS_SQLSERVER' => "日志备份是在上一次备份的基础上,对变化的日志数据进行备份,依赖于上一个日志时间点或增加时间点或差异时间点或完备时间点",
    'UI_STRATEGY_LOG_TOOLTIPS_ORACLE' => "归档日志备份是对最近给定天数的日志数据进行备份",
    'UI_STRATEGY_LOG_TOOLTIPS_DM' => "归档日志备份是对上一次备份后产生的所有日志数据进行备份,依赖于上一次备份时间点",
