    'UI_BACKUP_AUTO_NODE_TIPS' => "„ZAP“: Systém automaticky vyberie záložný uzol, do ktorého sa majú ukladať údaje; 'VYP': Manuálny výber zálohového uzla.",
    'UI_BACKUP_DIY_NODE' => "Definované užívateľom",
