    'UI_BACKUP_AUTO_STORAGE_TIPS' => "'ZAP': Systém automaticky vyberie optimálne úložisko pripojené k vybranému záložnému uzlu. 'VYP': Manuálne vyberie úložisko.",
    'UI_BACKUP_DIY_STORAGE' => "Definované užívateľom",
