    'UI_BACKUP_TRANSPORT_MODE' => "Prenos prostredníctvom ",
    'UI_BACKUP_TRANSPORT_NBD' => "LAN ",
    'UI_BACKUP_TRANSPORT_NBD_XENSERVER' => "NBD",
    'UI_BACKUP_TRANSPORT_NBD_SAN_XENSERVER' => "SAN+NBD",
    'UI_BACKUP_TRANSPORT_NBDSSL' => "Šifrovanie dát",
    'UI_BACKUP_TRANSPORT_SAN' => "SAN (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT' => "HOTADD (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT_VMWARE' => "HOTADD",
    'UI_BACKUP_TRANSPORT_SELECT_TIPS' => "LAN: Zálohované údaje sa majú prenesú z produktívneho úložiska do úložiska záloh LAN. <br> <br> SAN (LAN-Free): Zálohovacie údaje sa prenesú z z produktívneho úložiska do úložiska záloh prostredníctvom SAN. Na prenos cez SAN (LAN-Free) musíte najskôr pridať cestu LAN-Free z “LAN-Free Settings”. <br> <br> Šifrovanie dát: Keď sa dáta prenášajú cez LAN, SSL sa používa na šifrovanie prenášaných dát. <br> <br> HOTADD (LAN-Free): Na pripojenie cieľového disku VM k zálohovému serveru Vinchin na čítanie a zápis údajov použite funkciu VMware. <br> <br> Ak nie je k dispozícii prenos SAN, systém sa automaticky prepne na prenos LAN. ",
    'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => "LAN: Zálohované údaje sa majú prenesú z produktívneho úložiska do úložiska záloh LAN. <br> <br> SAN (LAN-Free): Zálohovacie údaje sa prenesú z z produktívneho úložiska do úložiska záloh prostredníctvom SAN. Na prenos cez SAN (LAN-Free) musíte najskôr pridať cestu LAN-Free z “LAN-Free Settings”. <br> <br> Šifrovanie dát: Keď sa dáta prenášajú cez LAN, SSL sa používa na šifrovanie prenášaných dát. <br> <br> HOTADD: 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问<br> <br> Ak nie je k dispozícii prenos SAN, systém sa automaticky prepne na prenos LAN. ",
    'UI_BACKUP_TRANSPORT_ICS_VVDK_SELECT_TIPS' => "LAN: Zálohované údaje sa majú prenesú z produktívneho úložiska do úložiska záloh LAN. ",
    'UI_BACKUP_TRANSPORT_SELECT_NBD_TIPS' => '【网络会自动切换，若有专用备份网络则优先使用专用网络传输，否则才会切换至管理网络进行传输】',
    'UI_BACKUP_TRANSPORT_HUAWEI_KVM_SELECT_TIPS' => "NBD传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_RHV_SELECT_TIPS' => "网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>ImageIO传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_TIPS' => "LAN: Údaje sa prenesú z produktívneho úložiska do úložiska záloh prostredníctvom siete LAN <br> <br> <br> SAN (LAN-Free): Záložné údaje sa prenesú z produktívneho úložiska do úložiska záloh pomocou SAN. Ak chcete prenášať prostredníctvom siete SAN (LAN-Free), musíte najprv pridať cestu LAN-Free z nastavení „LAN-Free Settings“. <br> <br> Šifrovanie dát: Zálohované dáta šifrované cez SSL <br> <br> Ak SAN prenos nie je k dispozícii, systém sa automaticky prepne na prenos LAN.",
    'UI_BACKUP_TRANSPORT_LEIXEN_SELECT_TIPS' => "LAN: Údaje sa prenesú z produktívneho úložiska do úložiska záloh prostredníctvom siete LAN <br> <br> <br> SAN (LAN-Free): Záložné údaje, sa prenesú z produktívneho úložiska do úložiska záloh pomocou SAN. Ak chcete prenášať údaje prostredníctvom siete SAN (bez LAN), musíte najskôr pridať cestu bez LAN z nastavení „LAN-Free Settings“. <br> <br> Ak nie je k dispozícii prenos SAN, systém sa automaticky prepne na prenos po sieti LAN.",
    'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS' => "LAN: Údaje sa prenesú z produktívneho úložiska do úložiska záloh prostredníctvom siete LAN <br> <br> <br> SAN (LAN-Free): Záložné údaje sa prenesú z produktívneho úložiska do úložiska záloh pomocou SAN. Ak chcete prenášať údaje prostredníctvom siete SAN (bez LAN), musíte najskôr pridať cestu bez LAN z nastavení „LAN-Free Settings“. <br> <br> NBD: Zálohovacie dáta sa prenesú pomocou NBD do zálohového úložiska, podpora XenServer7.3 a vyššie <br> <br> SAN + NBD: Zálohovacie dáta sa prenesú pomocou NBD + SAN na zálohovacie úložisko <br> <br> Ak nie je k dispozícii prenos SAN, systém sa automaticky prepne na prenos LAN.",
    'UI_BACKUP_TRANSPORT_HOTADD' => "Prenos HotAdd",
    'UI_BACKUP_DATA_RESERVE_TYPE_TIPS' => "Zásady uchovávania záložných údajov",
    'UI_BACKUP_MODE' => "Pokročilý režim zálohovania",
    'UI_BACKUP_MODE_TIPS' => "Pokročilé možnosti ľahšieho zálohovania",
    'UI_BACKUP_MODE_HIGH_SPEED' => "SpeedKit ",
    'UI_BACKUP_MODE_HIGH_SPEED_TIPS' => "SpeedKit vám môže pomôcť zvýšiť rýchlosť výpočtu zmenených blokov pri vykonávaní čiastkových záloh. Odporúča sa povoliť, ak chcete rýchlejšiu zálohu. (Predpoklad: Váš úložný priestor je dosť veľký.) <br><br>SpeedKit does not support Proxy.",
    'UI_BACKUP_INC_MODE_TIPS' => "SpeedKit je technológia Vinchin, ktorá zvyšuje rýchlosť výpočtu zmenených blokov pri vykonávaní čiastkových záloh. Odporúča sa vybrať, ak chcete rýchlejšiu zálohu alebo ak CBT nefunguje. (Predpoklad: Uistite sa, že váš úložný priestor je dosť veľký.) <br> <br> CBT je technológia Citrix na zvýšenie rýchlosti prírastkových záloh, podpora XenServer 7.3 a vyššie. <br> <br> Bežné: Venujte viac času vykonaniu čiastkových záloh.",
    'UI_BACKUP_INC_MODE_TIPS_EN' => "高速：备份完成后会保留一个快照,加快定位有效数据的速度<br><br>普通：不保留任何快照,在备份任务前需要更多时间计算有效数据",
    'UI_BACKUP_INC_MODE_CTB_TIPS' => " CBT je technológia Citrix na zvýšenie rýchlosti prírastkových záloh, podpora XenServer 7.3 a vyššie. ",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT' => "Quiesced snímka",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT_TIPS' => "Povolením funkcie „Quiesced Snapshot“ na udržanie súborových systémov alebo aplikácií vo virtuálnom počítači v konzistentnom stave prostredníctvom spracovania informácií o aplikácii (napr. VMware Tools) pred vytvorením snímky VM. <br> <br> Aplikácie v systéme Windows OS sú potrebné na podporu spoločnosti Microsoft VSS. <br> <br> Ak sa nepodarí zachytiť snímku v pokoji, systém urobí štandardnú snímku.",
    'UI_BACKUP_MODE_HIGH_HUAWEI_KVM_SILENTSNAPSHOT_TIPS' => "一致性快照可以通过应用感知程序,使文件系统或应用处于一致性状态<br><br>Windows操作系统需要应用支持VSS,才能保证应用的数据一致性<br><br>开启一致性快照后如果打一致性快照失败将自动再尝试打非一致性快照",
    'UI_BACKUP_MODE_HIGH_CBT_TIPS' => "Povolenie „CBT“ môže zvýšiť rýchlosť prírastkových záloh. Podporuje VM verzie 7 alebo vyššej.",
    'UI_BACKUP_MODE_HIGH_SNAPSHOT_TIPS' => "Serial ： Vytvorenie snímky každej VM a postupné dokončenie prenosu. <br> <br> Paralelne ： Súčasné vytvorenie snímky všetkých VM a následné dokončenie prenosu. Neodporúča sa vybrať, pokiaľ neexistuje obchodný vzťah medzi VM alebo keď sa nevyžaduje časová konzistentnosť všetkých zálohovaných údajov.",
    'UI_BACKUP_MODE_HIGH_VCBT_TIPS' => "Povoľte BitDetector, môžete ďalej zmenšiť veľkosť zálohy zo zdroja a znížiť zaťaženie siete",
    'UI_BACKUP_MODE_HIGH_SWAP_TIPS' => "Odkladací súbor sa používa ako dočasné umiestnenie na ukladanie informácií, ktoré RAM v súčasnosti nepoužíva, ako napríklad pagefile.sys / hiber.sys. Pretože sa údaje v odkladacích súboroch vždy menia, povolením tejto možnosti môžete preskočiť odkladacie súbory a vyhnúť sa zálohovaniu nepotrebných údajov.",
    'UI_BACKUP_MODE_HIGH_DELFILE_TIPS' => "Ak povolíte túto možnosť, súbory koša (napr. Súbory v koši) sa nebudú zálohovať.",
    'UI_BACKUP_MODE_HIGH_GAP_TIPS' => "Ak povolíte túto možnosť, diskový priestor bez oddielu (napr. Odstránený oddiel) na pevnom disku nebude zálohovaný.",
